with base as (select id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, status_bits - humidity as status_bits_minus_humidity, case when firmware = '1.0.3' then 1 else 0 end as is_1_0_3 from device_readings where firmware <> '2.0.1'), flagged as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval '1' hour then 1 else 0 end as new_group_flag from base), sessionized as (select id, device_code, reading_ts, status_bits_minus_humidity, is_1_0_3, sum(new_group_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from flagged) select case when session_id >= 6 then 'PREMIUM' else 'STANDARD' end as session_id_tier, case when status_bits_minus_humidity >= 65 then 'HIGH' else 'LOW' end as status_bits_minus_humidity_tier, count(*) filter (where device_code = 'DV-02') as dv_02_rows, count(case when device_code = 'DV-04' then 1 end) as dv_04_count, size(collect_set(device_code)) as num_device_codes, sum(case when device_code = 'DV-03' then session_id else 0 end) as dv_03_session_id from sessionized group by case when session_id >= 6 then 'PREMIUM' else 'STANDARD' end, case when status_bits_minus_humidity >= 65 then 'HIGH' else 'LOW' end order by session_id_tier desc;
